import { createContext, useContext, useState, useCallback, useRef } from 'react'
import api from '../api/client'

const AnalysisContext = createContext(null)

export function AnalysisProvider({ children }) {
  const [repo, setRepo] = useState(null)
  const [session, setSession] = useState(null)
  const [status, setStatus] = useState(null) // full status object
  const [results, setResults] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const pollRef = useRef(null)

  const loadDemo = useCallback(async () => {
    setLoading(true); setError(null)
    try {
      const data = await api.get('/repository/demo')
      setRepo(data)
      return data
    } catch (e) {
      setError(e.message)
      throw e
    } finally {
      setLoading(false)
    }
  }, [])

  const loadPath = useCallback(async (dirPath) => {
    setLoading(true); setError(null)
    try {
      const data = await api.post('/repository/path', { dirPath })
      setRepo(data)
      return data
    } catch (e) {
      setError(e.message)
      throw e
    } finally {
      setLoading(false)
    }
  }, [])

  const cloneRepo = useCallback(async (url) => {
    setLoading(true); setError(null)
    try {
      const data = await api.post('/repository/clone', { url })
      setRepo(data)
      return data
    } catch (e) {
      setError(e.message)
      throw e
    } finally {
      setLoading(false)
    }
  }, [])

  const startAnalysis = useCallback(async (repoId) => {
    setLoading(true); setError(null); setResults(null)
    try {
      const data = await api.post('/analysis/start', { repoId })
      setSession(data)
      pollStatus(data.sessionId)
      return data
    } catch (e) {
      setError(e.message)
      setLoading(false)
      throw e
    }
  }, [])

  const pollStatus = useCallback((sessionId) => {
    if (pollRef.current) clearInterval(pollRef.current)
    pollRef.current = setInterval(async () => {
      try {
        const st = await api.get(`/analysis/${sessionId}/status`)
        setStatus(st)
        setSession(prev => ({ ...prev, ...st }))

        if (st.status === 'complete') {
          clearInterval(pollRef.current)
          setLoading(false)
          const res = await api.get(`/analysis/${sessionId}/results`)
          setResults(res)
        } else if (st.status === 'error') {
          clearInterval(pollRef.current)
          setLoading(false)
          setError(st.error || 'Analysis failed')
        }
      } catch (e) {
        clearInterval(pollRef.current)
        setLoading(false)
      }
    }, 1500)
  }, [])

  const reset = useCallback(() => {
    if (pollRef.current) clearInterval(pollRef.current)
    setRepo(null); setSession(null); setStatus(null); setResults(null); setError(null); setLoading(false)
  }, [])

  return (
    <AnalysisContext.Provider value={{ repo, session, status, results, loading, error, loadDemo, loadPath, cloneRepo, startAnalysis, reset }}>
      {children}
    </AnalysisContext.Provider>
  )
}

export function useAnalysis() {
  const ctx = useContext(AnalysisContext)
  if (!ctx) throw new Error('useAnalysis must be used within AnalysisProvider')
  return ctx
}
